// Official PNG embedded unchanged so local and isolated previews need no image request.
const officialLogoSrc="data:image/png;base64,";
const svg=(type)=>type==='plane'?`<svg class="plane" viewBox="0 0 600 360" role="img" aria-label="Aircraft illustration"><path d="M33 217 224 162 274 57 297 54 280 157 509 185Q570 190 572 204Q568 218 510 218L280 213 300 302 277 305 225 217 63 244Z" fill="#fafbf8" stroke="#8d9693" stroke-width="2"/><path d="m224 162 56-5v56l-55 4Z" fill="#dee3df"/><path d="M54 216 510 199" stroke="#d9b724" stroke-width="4"/><path d="m501 189 18 4 8 8-27-2Z" fill="#253d40"/><path d="m283 94 40 7v23l-44-5M284 249l40 1v24l-36-5" fill="#899995" stroke="#5f706c"/><path d="m65 206-14-63 18-2 45 51" fill="#f2d32b"/><path d="m51 143 19-2 6 9-23 4Z" fill="#b43f35"/></svg>`:type==='book'?`<svg viewBox="0 0 400 300" role="img" aria-label="Logbook illustration"><g transform="rotate(-12 200 150)"><rect x="118" y="35" width="163" height="232" rx="6" fill="#233c43"/><path d="M130 39v222" stroke="#668084"/><rect x="144" y="62" width="110" height="177" fill="none" stroke="#b7a36b"/><text x="200" y="105" text-anchor="middle" fill="#d9c38c" font-family="Arial" font-size="12">TIRIO</text><path d="m168 156 64-22-26 26 15 25-24-17-20 3 9-13Z" fill="#d9c38c"/><text x="200" y="215" text-anchor="middle" fill="#d9c38c" font-family="Arial" font-size="9">FLIGHT LOGBOOK</text></g></svg>`:`<svg viewBox="0 0 400 300" role="img" aria-label="Luggage tag illustration"><g transform="rotate(-18 200 150)"><circle cx="113" cy="150" r="29" fill="none" stroke="#8e9390" stroke-width="8"/><rect x="126" y="119" width="192" height="64" rx="5" fill="#edcf32"/><rect x="301" y="119" width="17" height="64" fill="#bd4336"/><path d="M133 126h160v50H133Z" fill="none" stroke="#99832a" stroke-dasharray="3 3"/><text x="213" y="160" text-anchor="middle" font-size="29" font-weight="bold" font-family="Arial" fill="#252921">TIRIO 30</text></g></svg>`;
const copy={es:{notice:'CATÁLOGO CONCEPTUAL · PRÓXIMAMENTE · COMPRAS NO DISPONIBLES',shop:'Catálogo',about:'Sobre TIRIO',hero:'Tu próxima colección<br>empieza aquí.',desc:'Explora modelos de aviones, coleccionables y nuevos conceptos TIRIO.',explore:'Explorar la colección',categories:'Explora por categoría',featured:'Selección TIRIO',all:'Ver todo →',detail:'Ver concepto',soon:'Próximamente',concept:'Concepto · no disponible para compra',photo:'Fotografía de producto pendiente',demo:'Catálogo de demostración. Conceptos ilustrativos, sin inventario disponible ni pedidos o pagos.',search:'Buscar en el catálogo…',sort:'Selección TIRIO',az:'Nombre: A–Z',none:'No se encontraron conceptos.',back:'Volver al catálogo',specs:'Información del concepto',scale:'Formato propuesto',material:'Material propuesto',status:'Estado',coffeeTitle:'TIRIO Coffee',coffeeDesc:'Una nueva escala en tu rutina. Descubre nuestro concepto de café y accesorios de inspiración aeronáutica.',coffeeCta:'Explorar TIRIO Coffee →',story:'Aviation & Collectibles',storyDesc:'TIRIO reúne la pasión por la aviación, el diseño y el coleccionismo. Las colecciones presentadas están en desarrollo.',disabled:'Compras no disponibles',cartInfo:'Este prototipo funciona únicamente como catálogo. No hay cesta, pedidos, pagos ni proceso de compra.',theme:'Tema',light:'Claro',dark:'Oscuro',auto:'Auto',language:'Idioma',category:'Categoría',allCategories:'Todas las categorías',placeholder:'Imagen de referencia pendiente',preview:'Vista de colección'},en:{notice:'CONCEPT CATALOG · COMING SOON · PURCHASING UNAVAILABLE',shop:'Catalog',about:'About TIRIO',hero:'Your next collection<br>starts here.',desc:'Explore aircraft models, collectibles and new TIRIO concepts.',explore:'Explore the collection',categories:'Shop by category',featured:'TIRIO selection',all:'View all →',detail:'View concept',soon:'Coming soon',concept:'Concept · not available to purchase',photo:'Product photography pending',demo:'Demonstration catalog. Illustrative concepts, with no available inventory, orders or payments.',search:'Search the catalog…',sort:'TIRIO selection',az:'Name: A–Z',none:'No concepts found.',back:'Back to catalog',specs:'Concept information',scale:'Proposed format',material:'Proposed material',status:'Status',coffeeTitle:'TIRIO Coffee',coffeeDesc:'A new stop in your daily routine. Discover our aviation-inspired coffee and accessories concept.',coffeeCta:'Explore TIRIO Coffee →',story:'Aviation & Collectibles',storyDesc:'TIRIO brings together aviation, design and collecting. The collections shown are in development.',disabled:'Purchasing unavailable',cartInfo:'This prototype is a catalog only. There is no bag, ordering, payment or checkout flow.',theme:'Theme',light:'Light',dark:'Dark',auto:'Auto',language:'Language',category:'Category',allCategories:'All categories',placeholder:'Reference image pending',preview:'Collection preview'}};
const categories=[{id:'models',name:'Aircraft Models',es:'Modelos de aviones',en:'Aircraft models',type:'plane'},{id:'collectibles',name:'Aviation Collectibles',es:'Objetos de colección',en:'Aviation collectibles',type:'tag'},{id:'originals',name:'TIRIO Originals',es:'Diseño original TIRIO',en:'Original TIRIO design',type:'book'},{id:'coffee',name:'TIRIO Coffee',es:'Café y accesorios · concepto',en:'Coffee & accessories · concept',type:'coffee'}];
const products=[{id:'model',category:'models',es:'Modelo de avión · White Edition',en:'Aircraft model · White Edition',type:'plane',scale:'1:200',material:{es:'Metal / resina',en:'Metal / resin'}},{id:'tag',category:'collectibles',es:'Etiqueta de equipaje · Runway 30',en:'Luggage tag · Runway 30',type:'tag',scale:'12 × 4 cm',material:{es:'Textil',en:'Textile'}},{id:'logbook',category:'originals',es:'Cuaderno de vuelo · Midnight',en:'Flight logbook · Midnight',type:'book',scale:'A6',material:{es:'Papel',en:'Paper'}},{id:'coffee',category:'coffee',es:'TIRIO Coffee · Ground Edition',en:'TIRIO Coffee · Ground Edition',type:'coffee',scale:'250 g',material:{es:'Café · mezcla por definir',en:'Coffee · blend to be defined'}}];
const safeGet=(key,fallback)=>{try{return localStorage.getItem(key)||fallback}catch{return fallback}};
let lang=safeGet('tirio-lang','es');if(!copy[lang])lang='es';let theme=safeGet('tirio-theme','system');if(!['system','light','dark'].includes(theme))theme='system';
let query='',order='',galleryView=0;const systemTheme=matchMedia('(prefers-color-scheme: dark)'),t=()=>copy[lang];
function save(){try{localStorage.setItem('tirio-lang',lang);localStorage.setItem('tirio-theme',theme)}catch{/* Storage may be unavailable when opened as a local file. */}}
function applyTheme(){document.body.classList.toggle('dark',theme==='dark'||theme==='system'&&systemTheme.matches);document.documentElement.style.colorScheme=theme==='system'?(systemTheme.matches?'dark':'light'):theme}
function currentCategory(){return categories.find(c=>location.hash==='#category/'+c.id)}
function art(type){return type==='coffee'?`<svg viewBox="0 0 400 300" role="img" aria-label="${t().placeholder}"><ellipse cx="202" cy="251" rx="76" ry="9" fill="#000" opacity=".08"/><path d="M148 49h107l15 198H133Z" fill="#303236"/><path d="M148 49h107l5 23H145Z" fill="#55585c"/><rect x="153" y="109" width="97" height="87" fill="#fff"/><text x="202" y="133" text-anchor="middle" fill="#191919" font-size="14" font-family="Arial" font-weight="bold">TIRIO</text><text x="202" y="154" text-anchor="middle" fill="#191919" font-size="12" font-family="Arial">COFFEE</text><path d="M178 169h48" stroke="#f3cf20" stroke-width="4"/><text x="202" y="185" text-anchor="middle" fill="#555" font-size="8" font-family="Arial">CONCEPT / 250 g</text></svg>`:svg(type).replace(/aria-label="[^"]*"/,`aria-label="${t().placeholder}"`)}
function image(p){return `<div class="product-image"><span class="tag">${t().soon}</span>${art(p.type)}<span class="photo-label">${t().photo}</span></div>`}
function card(p){return `<a class="product" href="#product/${p.id}">${image(p)}<div class="product-meta"><span class="eyebrow">${categories.find(c=>c.id===p.category).name}</span><h3>${p[lang]}</h3><span class="product-status">${t().concept}</span></div><small>${t().detail} →</small></a>`}
function categoryLinks(){return categories.map(c=>`<a href="${c.id==='coffee'?'#coffee':'#category/'+c.id}">${c.name}</a>`).join('')}
function render(){document.documentElement.lang=lang;applyTheme();const route=location.hash.slice(1)||'home';document.getElementById('app').innerHTML=`<div class="notice">${t().notice}</div><header><button class="menu" aria-label="Menu" aria-expanded="false" aria-controls="mobile-nav">☰</button><a class="brand" href="#home" aria-label="TIRIO 30 home"><img src="${officialLogoSrc}" alt="TIRIO 30" width="1637" height="391"></a><nav aria-label="${t().shop}"><a href="#shop">${t().shop}</a><a href="#category/originals">TIRIO Originals</a><a href="#coffee">TIRIO Coffee</a><a href="#story">${t().about}</a></nav><div class="tools"><select id="lang" aria-label="${t().language}">${['es','en'].map(l=>`<option value="${l}" ${lang===l?'selected':''}>${l.toUpperCase()}</option>`).join('')}</select><select id="theme" aria-label="${t().theme}">${['system','light','dark'].map(x=>`<option value="${x}" ${theme===x?'selected':''}>${x==='system'?t().auto:x==='light'?t().light:t().dark}</option>`).join('')}</select></div></header><div id="mobile-nav" class="menu-links"><a href="#shop">${t().shop}</a>${categoryLinks()}<a href="#story">${t().about}</a></div><main>${route==='home'?home():route==='coffee'?coffeeLanding():route==='shop'||route.startsWith('category/')?shop():route==='story'?story():route==='cart'||route==='checkout'?cartView():route.startsWith('product/')?detail(route.split('/')[1]):home()}</main><footer><a class="footer-brand" href="#home"><img src="${officialLogoSrc}" alt="TIRIO 30" width="1637" height="391" loading="lazy"></a><p>${t().demo}</p><a href="#coffee">TIRIO Coffee →</a></footer>`;bind()}
function home(){return `<div class="hero"><div class="hero-copy"><span class="eyebrow">TIRIO / AVIATION & COLLECTIBLES</span><h1>${t().hero}</h1><p>${t().desc}</p><a class="btn yellow" href="#shop">${t().explore} →</a></div><div class="hero-art">${art('plane')}<span class="art-label">${t().preview} · ${t().placeholder}</span></div></div><section aria-labelledby="categories-title"><div class="section-heading"><h2 id="categories-title">${t().categories}</h2><span class="eyebrow">04 COLLECTIONS</span></div><div class="categories">${categories.map((c,i)=>`<a class="category-card" href="#category/${c.id}"><span class="category-number">0${i+1}</span><div class="category-art">${art(c.type)}</div><h3>${c.name} <span>→</span></h3><p>${c[lang]}</p></a>`).join('')}</div></section><section class="featured"><div class="section-heading"><div><span class="eyebrow">AVIATION & COLLECTIBLES</span><h2>${t().featured}</h2></div><a href="#shop">${t().all}</a></div><div class="grid">${products.map(card).join('')}</div></section><section class="coffee-section"><div class="coffee-art">${art('coffee')}</div><div><span class="eyebrow">${t().soon} / TIRIO COFFEE</span><h2>${t().coffeeTitle}</h2><p>${t().coffeeDesc}</p><p class="demo">${t().concept}</p><a class="btn" href="#coffee">${t().coffeeCta}</a></div></section>`}
function story(){return `<section class="intro"><span class="eyebrow">TIRIO 30</span><h1>${t().story}</h1><p>${t().storyDesc}</p><a class="btn" href="#shop">${t().explore} →</a></section>`}
function shop(){const c=currentCategory();return `<section><div class="breadcrumb"><a href="#shop">${t().shop}</a>${c?' / '+c.name:''}</div><h1>${c?c.name:t().shop}</h1><p class="demo">${t().demo}</p><div class="category-tabs"><a href="#shop" ${!c?'aria-current="page"':''}>${t().allCategories}</a>${categories.map(k=>`<a href="#category/${k.id}" ${c&&c.id===k.id?'aria-current="page"':''}>${k.name}</a>`).join('')}</div><div class="filters"><input id="search" type="search" aria-label="${t().search}" placeholder="${t().search}"><select id="sort" aria-label="${t().sort}"><option value="">${t().sort}</option><option value="az">${t().az}</option></select></div><p id="result-count" class="demo" aria-live="polite"></p><div class="grid" id="results"></div></section>`}
function results(){const c=currentCategory();let list=products.filter(p=>(!c||p.category===c.id)&&(p[lang]+' '+categories.find(k=>k.id===p.category).name).toLocaleLowerCase(lang).includes(query.toLocaleLowerCase(lang)));if(order==='az')list.sort((a,b)=>a[lang].localeCompare(b[lang],lang));document.getElementById('result-count').textContent=String(list.length)+' / '+t().featured;document.getElementById('results').innerHTML=list.length?list.map(card).join(''):`<p>${t().none}</p>`}
function detail(id){const p=products.find(p=>p.id===id);if(!p)return `<section><h1>${t().none}</h1><a href="#shop">${t().back}</a></section>`;const c=categories.find(c=>c.id===p.category);return `<div class="breadcrumb"><a href="#shop">${t().shop}</a> / <a href="#category/${c.id}">${c.name}</a></div><div class="detail">${gallery(p)}<div><span class="eyebrow">${c.name}</span><h1>${p[lang]}</h1><span class="status-label">${t().soon}</span><p class="product-description">${descriptions[p.id][lang]}</p><p>${t().concept}</p><p class="demo">${t().demo}</p><p class="catalog-notice">${t().disabled}</p><h2>${t().specs}</h2><div class="spec"><span>${t().scale}</span><span>${p.scale}</span></div><div class="spec"><span>${t().material}</span><span>${p.material[lang]}</span></div><div class="spec"><span>${t().status}</span><span>${t().soon}</span></div></div></div>`}
function cartView(){return `<section class="empty"><h1>${t().disabled}</h1><p>${t().cartInfo}</p><a class="btn" href="#shop">${t().back} →</a></section>`}
function bind(){document.querySelectorAll('[data-gallery-view]').forEach(button=>button.onclick=()=>{galleryView=Number(button.dataset.galleryView);render();document.querySelector('[data-gallery-view="'+galleryView+'"]').focus()});document.getElementById('lang').onchange=e=>{lang=e.target.value;save();render()};document.getElementById('theme').onchange=e=>{theme=e.target.value;save();render()};document.querySelector('.menu').onclick=e=>{const open=document.querySelector('.menu-links').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))};const search=document.getElementById('search');if(search){search.value=query;document.getElementById('sort').value=order;results();search.oninput=e=>{query=e.target.value;results()};document.getElementById('sort').onchange=e=>{order=e.target.value;results()}}}

const descriptions={model:{es:'Concepto de modelo de avión comercial para una futura colección TIRIO. La escala, los materiales y el acabado son propuestas pendientes de confirmar; la ilustración no representa un artículo en stock.',en:'A commercial aircraft model concept for a future TIRIO collection. Scale, materials and finish are proposals awaiting confirmation; the illustration does not represent stocked merchandise.'},tag:{es:'Propuesta de etiqueta de equipaje inspirada en la señalización de pista. Diseño, medidas y fabricación por confirmar. No es un producto a la venta.',en:'A luggage tag proposal inspired by runway signage. Design, dimensions and production remain unconfirmed. This is not merchandise for sale.'},logbook:{es:'Concepto de cuaderno para registrar recuerdos de vuelo. Formato, papel y contenido editorial por definir. Se muestra únicamente como demostración del catálogo.',en:'A notebook concept for recording flight memories. Format, paper and editorial content are to be defined. Shown solely to demonstrate the catalog.'},coffee:{es:'Propuesta de café en grano para TIRIO Coffee. Origen, tueste, mezcla y envase por definir. La presentación es conceptual y no constituye una oferta comercial.',en:'A coffee bean proposal for TIRIO Coffee. Origin, roast, blend and packaging are to be defined. This conceptual presentation is not a commercial offer.'}};
const galleryLabels={es:['Vista general','Detalle ilustrativo'],en:['Overview','Illustrative detail']};
function gallery(p){return `<div class="gallery"><div id="gallery-stage" class="gallery-stage view-${galleryView}" role="region" aria-label="${galleryLabels[lang][galleryView]}" aria-live="polite">${image(p)}</div><div class="gallery-thumbnails" aria-label="${lang==='es'?'Vistas del concepto':'Concept views'}">${galleryLabels[lang].map((label,i)=>`<button type="button" data-gallery-view="${i}" aria-pressed="${galleryView===i}" aria-controls="gallery-stage"><span aria-hidden="true">${art(p.type)}</span><span>${label}</span></button>`).join('')}</div><p class="demo">${lang==='es'?'Ambas vistas usan la misma ilustración de demostración. Fotografías y vistas reales pendientes.':'Both views use the same demonstration illustration. Actual photography and product views are pending.'}</p></div>`}
function coffeeLanding(){const future=lang==='es'?[['Café en grano','Origen, tueste y formatos por definir.'],['Equipamiento de preparación','Futuros conceptos de cafeteras y utensilios.'],['Accesorios de café aeronáuticos','Objetos para acompañar tu próxima pausa.']]:[['Coffee beans','Origin, roast and formats to be defined.'],['Brewing equipment','Future concepts for brewers and tools.'],['Aviation-themed coffee accessories','Objects for your next coffee break.']];return `<div class="breadcrumb"><a href="#home">TIRIO</a> / TIRIO Coffee</div><section class="coffee-section coffee-landing"><div class="coffee-art">${art('coffee')}</div><div><span class="eyebrow">${t().soon} / ${t().concept}</span><h1>TIRIO Coffee</h1><p>${t().coffeeDesc}</p><p class="demo">${t().demo}</p><a class="btn" href="#category/coffee">${t().explore} →</a></div></section><section><h2>${lang==='es'?'Futuras categorías':'Future categories'}</h2><div class="coffee-future">${future.map(([name,desc])=>`<article><span class="eyebrow">${t().soon}</span><h3>${name}</h3><p>${desc}</p><span class="demo">${t().concept}</span></article>`).join('')}</div></section><section><div class="section-heading"><h2>${lang==='es'?'Conceptos en desarrollo':'Concepts in development'}</h2><a href="#category/coffee">${t().all}</a></div><div class="grid">${products.filter(p=>p.category==='coffee').map(card).join('')}</div></section>`}

window.addEventListener('hashchange',()=>{query='';galleryView=0;render();window.scrollTo(0,0)});systemTheme.addEventListener('change',()=>{if(theme==='system')applyTheme()});render();
